// Spanish wording for the whole site (used by i18n.js when ES is on).
// ES: exact screen text → Spanish. PATTERNS: whole lines that carry numbers or names.
// FRAGMENTS: sentences inside longer messages. To fix a word, change it here.

const N = (s) => s; // numbers / sizes pass through
const shiftEs = { '1st': '1ro', '2nd': '2do' };
const stationEs = { '1st': '1ra', '2nd': '2da' };
const plural = (n, one, many) => (String(n).replace(/,/g, '') === '1' ? one : many);
const qtyWords = (s) => s.replace(/\bboxes\b/g, 'cajas').replace(/\bblanks\b/g, 'blanks');
const DAYS = { Mon: 'lun', Tue: 'mar', Wed: 'mié', Thu: 'jue', Fri: 'vie', Sat: 'sáb', Sun: 'dom' };
