// "48 × 48 pallet" / "2 × 48 × 40 pallets side by side (96 × 40 base)"
function palletLabelEs(l) {
  let m = l.match(/^(.+) pallet$/);
  if (m) return `tarima ${m[1]}`;
  m = l.match(/^2 × (.+) pallets (side by side|end to end) \((.+) base\)$/);
  if (m) return `2 tarimas ${m[1]} ${m[2] === 'side by side' ? 'lado a lado' : 'una tras otra'} (base ${m[3]})`;
  return l;
}
